import{_ as e,o,c as s,a5 as n}from"./chunks/framework.DJo0M80U.js";const c=JSON.parse('{"title":"Vue 3 拖拽布局库","description":"在 Vue 3 中，实现页面分区域布局并支持拖拽调整边界的功能，以下是国内最受欢迎的库以及实现思路： 国内最受欢迎的 Vue 3 拖拽布局库 1. Splitpanes 特点 ：轻量级、纯 Vue 3 实现，支持水平和垂直分割，拖拽流畅。 适用场景 ：类似 VS Code 的面板。","frontmatter":{"title":"Vue 3 拖拽布局库","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","工程化、质量与性能"],"description":"在 Vue 3 中，实现页面分区域布局并支持拖拽调整边界的功能，以下是国内最受欢迎的库以及实现思路： 国内最受欢迎的 Vue 3 拖拽布局库 1. Splitpanes 特点 ：轻量级、纯 Vue 3 实现，支持水平和垂直分割，拖拽流畅。 适用场景 ：类似 VS Code 的面板。","sidebarWeight":12,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/实用包/Vue 3 拖拽布局库.md"},"headers":[],"relativePath":"posts/Vue系统教程/06-工程化、质量与性能/Vue 3 拖拽布局库.md","filePath":"posts/Vue系统教程/06-工程化、质量与性能/Vue 3 拖拽布局库.md"}'),l={name:"posts/Vue系统教程/06-工程化、质量与性能/Vue 3 拖拽布局库.md"};function r(i,t,a,g,u,p){return o(),s("div",null,[...t[0]||(t[0]=[n('<div><h1 id="vue-3-拖拽布局库" tabindex="-1">Vue 3 拖拽布局库 <a class="header-anchor" href="#vue-3-拖拽布局库" aria-label="Permalink to &quot;Vue 3 拖拽布局库&quot;">​</a></h1><blockquote><p>本节目标：理解“Vue 3 拖拽布局库”的核心思路，并能把它用于实际开发或面试表达。 在 Vue 3 中，实现页面分区域布局并支持拖拽调整边界的功能，以下是国内最受欢迎的库以及实现思路：</p></blockquote><p><strong>国内最受欢迎的 Vue 3 拖拽布局库</strong><strong>1.</strong> <strong>Splitpanes</strong></p><ul><li><strong>特点</strong>==：轻量级、纯 Vue 3 实现，支持水平和垂直分割，拖拽流畅。==</li><li><strong>适用场景</strong>==：类似 VS Code 的面板拖拽调整。==</li><li><strong>npm 安装</strong>==：========bash========复制========npm== ==install== ==splitpanes==</li></ul><p><strong>2.</strong> <strong>Vue Grid Layout</strong></p><ul><li><strong>特点</strong>==：类似 Trello/看板布局，支持拖拽、缩放、响应式。==</li><li><strong>适用场景</strong>==：仪表盘、可拖拽卡片布局。==</li><li><strong>npm 安装</strong>==：========bash========复制========npm== ==install== ==vue-grid-layout@next==</li></ul><p><strong>3.</strong> <strong>Vue Draggable Resizable</strong></p><ul><li><strong>特点</strong>==：支持拖拽 + 调整大小，适合自由布局。==</li><li><strong>npm 安装</strong>==：========bash========复制========npm== ==install== ==vue-draggable-resizable==</li></ul><p><strong>4.</strong> <strong>Element Plus 的 Split 组件</strong></p><ul><li><strong>特点</strong>==：基于 Element UI，适合后台管理系统，简单易用。==</li><li><strong>npm 安装</strong>==：========bash========复制========npm== ==install== ==element-plus==</li></ul><p><strong>实现思路（以</strong> <strong>Splitpanes</strong> <strong>为例）</strong><strong>1. 安装 Splitpanes</strong> bash 复制 npm install splitpanes <strong>2. 基本使用（水平/垂直分割）</strong> vue 复制 &lt;template&gt; &lt;Splitpanes class=&quot;default-theme&quot; @resize=&quot;onResize&quot;&gt; &lt;Pane min-size=&quot;20&quot; size=&quot;25&quot;&gt;左侧面板&lt;/Pane&gt; &lt;Pane size=&quot;50&quot;&gt;中间面板&lt;/Pane&gt; &lt;Pane min-size=&quot;20&quot; size=&quot;25&quot;&gt;右侧面板&lt;/Pane&gt; &lt;/Splitpanes&gt;&lt;/template&gt; &lt;script setup&gt;import { Splitpanes, Pane } from &quot;splitpanes&quot;;import &quot;splitpanes/dist/splitpanes.css&quot;; const onResize = (sizes) =&gt; { console.log(&quot;面板尺寸变化:&quot;, sizes);};&lt;/script&gt; &lt;style&gt;.splitpanes__splitter { background: #eee; position: relative;}.splitpanes__splitter:before { content: &quot;&quot;; position: absolute; left: 0; top: 0; width: 100%; height: 100%; background: #ccc; opacity: 0.3; transition: opacity 0.3s;}.splitpanes__splitter:hover:before { opacity: 1;}&lt;/style&gt; <strong>3. 进阶用法（嵌套拖拽）</strong> vue 复制 &lt;template&gt; &lt;Splitpanes horizontal&gt; &lt;Pane size=&quot;30&quot;&gt; &lt;Splitpanes&gt; &lt;Pane size=&quot;50&quot;&gt;左上&lt;/Pane&gt; &lt;Pane size=&quot;50&quot;&gt;右上&lt;/Pane&gt; &lt;/Splitpanes&gt; &lt;/Pane&gt; &lt;Pane size=&quot;70&quot;&gt; &lt;Splitpanes&gt; &lt;Pane size=&quot;30&quot;&gt;左下&lt;/Pane&gt; &lt;Pane size=&quot;70&quot;&gt;右下&lt;/Pane&gt; &lt;/Splitpanes&gt; &lt;/Pane&gt; &lt;/Splitpanes&gt;&lt;/template&gt;</p><p><strong>实现思路（以</strong> <strong>Vue Grid Layout</strong> <strong>为例）</strong><strong>1. 安装 Vue Grid Layout</strong> bash 复制 npm install vue-grid-layout@next <strong>2. 基本使用（可拖拽看板）</strong> vue 复制 &lt;template&gt; &lt;GridLayout :layout=&quot;layout&quot; :col-num=&quot;12&quot; :row-height=&quot;30&quot; @layout-updated=&quot;onLayoutUpdated&quot; &gt; &lt;GridItem v-for=&quot;item in layout&quot; :key=&quot;item.i&quot; :x=&quot;item.x&quot; :y=&quot;item.y&quot; :w=&quot;item.w&quot; :h=&quot;item.h&quot; &gt; {{ <code>Panel ${item.i}</code> }} &lt;/GridItem&gt; &lt;/GridLayout&gt;&lt;/template&gt; &lt;script setup&gt;import { ref } from &quot;vue&quot;;import { GridLayout, GridItem } from &quot;vue-grid-layout&quot;; const layout = ref([ { x: 0, y: 0, w: 4, h: 4, i: &quot;1&quot; }, { x: 4, y: 0, w: 4, h: 4, i: &quot;2&quot; }, { x: 8, y: 0, w: 4, h: 4, i: &quot;3&quot; },]); const onLayoutUpdated = (newLayout) =&gt; { console.log(&quot;布局更新:&quot;, newLayout);};&lt;/script&gt;</p><p><strong>总结</strong></p><table tabindex="0"><thead><tr><th></th><th></th><th></th><th></th></tr></thead><tbody><tr><td>库</td><td>适用场景</td><td>特点</td><td>推荐指数</td></tr><tr><td><strong>Splitpanes</strong></td><td>面板分割（类似 VS Code）</td><td>轻量、流畅</td><td>⭐⭐⭐⭐⭐</td></tr><tr><td><strong>Vue Grid Layout</strong></td><td>看板/仪表盘</td><td>拖拽+缩放</td><td>⭐⭐⭐⭐</td></tr><tr><td><strong>Vue Draggable Resizable</strong></td><td>自由布局</td><td>可调整大小</td><td>⭐⭐⭐</td></tr><tr><td><strong>Element Plus Split</strong></td><td>简单分割</td><td>集成 Element UI</td><td>⭐⭐⭐</td></tr></tbody></table><p><strong>推荐选择</strong></p><ul><li><strong>如果需要类似 IDE 的分割面板</strong> ==→== <strong>Splitpanes</strong></li><li><strong>如果需要可拖拽的卡片布局</strong> ==→== <strong>Vue Grid Layout</strong></li><li><strong>如果项目已用 Element Plus</strong> ==→== <strong>Element Plus Split</strong></li><li><strong>如果需要自由拖拽 + 调整大小</strong> ==→== <strong>Vue Draggable Resizable</strong></li></ul><p>你可以根据具体需求选择合适的库！ 🚀 &gt; 来自 &lt;<a href="https://chat.deepseek.com/a/chat/s/9c2caa9b-a223-4340-802e-82a4b5410ff9" target="_blank" rel="noreferrer">https://chat.deepseek.com/a/chat/s/9c2caa9b-a223-4340-802e-82a4b5410ff9</a>&gt;</p><p>了解！你想深入探讨这些库的<strong>源码实现思路</strong>，而不仅仅是使用方式。下面我会分析 <strong>Splitpanes</strong> 和 <strong>Vue Grid Layout</strong> 这两个典型库的核心实现逻辑，帮助你理解它们是如何在底层实现拖拽分割和动态布局的。</p><p><strong>1. Splitpanes 源码实现思路</strong><strong>核心功能</strong>==：支持面板分割 + 拖拽调整边界。== <strong>源码关键点</strong>==（简化版逻辑）：== <strong>(1) DOM 结构</strong> html 复制 &lt;div class=&quot;splitpanes&quot;&gt; &lt;div class=&quot;splitpanes__pane&quot;&gt;面板1&lt;/div&gt; &lt;div class=&quot;splitpanes__splitter&quot;&gt;&lt;/div&gt; &lt;!-- 拖拽条 --&gt; &lt;div class=&quot;splitpanes__pane&quot;&gt;面板2&lt;/div&gt;&lt;/div&gt;</p><p>运行 HTML</p><ul><li><strong>splitpanes__splitter</strong> ==是拖拽手柄，用户通过它调整相邻面板大小。==</li></ul><p><strong>(2) 拖拽事件绑定</strong> javascript 复制 // 源码关键部分（伪代码）splitter.addEventListener(&#39;mousedown&#39;, (e) =&gt; { e.preventDefault(); document.addEventListener(&#39;mousemove&#39;, onMouseMove); document.addEventListener(&#39;mouseup&#39;, onMouseUp);}); function onMouseMove(e) { // 计算鼠标移动距离（deltaX/deltaY） const delta = horizontal ? e.clientX - startX : e.clientY - startY; // 计算新尺寸（按比例分配） const newSizes = calculateNewSizes(delta); // 更新面板宽度/高度 panes.forEach((pane, i) =&gt; { pane.style.flexBasis = <code>${newSizes[i]}%</code>; });}</p><ul><li><strong>核心逻辑</strong>==：通过== ==mousemove== ==计算鼠标偏移量，动态调整相邻面板的== ==flexBasis====。==</li></ul><p><strong>(3) 尺寸计算</strong> javascript 复制 function calculateNewSizes(delta) { // 总容器尺寸 const totalSize = horizontal ? container.offsetWidth : container.offsetHeight; // 当前面板尺寸（百分比） const pane1Size = (pane1.offsetWidth / totalSize) * 100; const pane2Size = (pane2.offsetWidth / totalSize) * 100; // 调整后的新尺寸 const newPane1Size = pane1Size + (delta / totalSize) * 100; const newPane2Size = pane2Size - (delta / totalSize) * 100; return [newPane1Size, newPane2Size];}</p><ul><li><strong>关键点</strong>==：使用== <strong>flexbox</strong> <strong>+ 百分比计算</strong>==，确保拖拽时面板按比例缩放。==</li></ul><p><strong>(4) 嵌套支持</strong> ==通过递归组件实现嵌套分割：== vue 复制 &lt;Splitpanes&gt; &lt;Pane&gt; &lt;Splitpanes&gt; &lt;!-- 嵌套 --&gt; &lt;Pane&gt;子面板1&lt;/Pane&gt; &lt;Pane&gt;子面板2&lt;/Pane&gt; &lt;/Splitpanes&gt; &lt;/Pane&gt;&lt;/Splitpanes&gt;</p><p><strong>2. Vue Grid Layout 源码实现思路</strong><strong>核心功能</strong>==：支持动态网格布局（类似 Trello）。== <strong>源码关键点</strong>==：== <strong>(1) 数据驱动布局</strong> javascript 复制 layout: [ { x: 0, y: 0, w: 2, h: 2, i: &quot;1&quot; }, // x/y 是网格坐标，w/h 是宽高 { x: 2, y: 0, w: 2, h: 4, i: &quot;2&quot; }]</p><ul><li><strong>网格系统</strong>==：所有元素的位置和大小通过== ==x, y, w, h== ==描述。==</li></ul><p><strong>(2) 拖拽实现</strong> javascript 复制 // 伪代码：拖拽事件处理onDragStart(item) { // 记录初始位置 this.draggingItem = { ...item, offsetX: event.clientX, offsetY: event.clientY };}, onDrag(event) { // 计算新位置（基于网格） const gridX = Math.floor((event.clientX - this.draggingItem.offsetX) / this.colWidth); const gridY = Math.floor((event.clientY - this.draggingItem.offsetY) / this.rowHeight); // 更新布局数据 this.layout.find(item =&gt; item.i === this.draggingItem.i).x = gridX; this.layout.find(item =&gt; item.i === this.draggingItem.i).y = gridY;}</p><ul><li><strong>关键点</strong>==：将像素坐标转换为网格坐标（====colWidth== ==和== ==rowHeight== ==是预设值）。==</li></ul><p><strong>(3) 碰撞检测</strong> javascript 复制 // 检查目标位置是否已被占用function isPositionAvailable(x, y, w, h, excludeId) { return !this.layout.some(item =&gt; { if (item.i === excludeId) return false; return ( x &lt; item.x + item.w &amp;&amp; x + w &gt; item.x &amp;&amp; y &lt; item.y + item.h &amp;&amp; y + h &gt; item.y ); });}</p><ul><li><strong>算法</strong>==：基于== <strong>AABB（轴对齐边界框）碰撞检测</strong>==。==</li></ul><p><strong>(4) 响应式调整</strong> javascript 复制 // 监听窗口大小变化，重新计算布局window.addEventListener(&#39;resize&#39;, () =&gt; { this.containerWidth = this.$el.offsetWidth; this.colWidth = this.containerWidth / this.colNum; // 重新计算列宽});</p><ul><li><strong>核心</strong>==：通过== ==resize== ==事件动态调整== ==colWidth== ==和== ==rowHeight====。==</li></ul><p><strong>3. 通用实现思路总结</strong></p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>功能</td><td>实现方案</td></tr><tr><td><strong>拖拽手柄</strong></td><td>监听 mousedown/mousemove/mouseup，计算偏移量并更新 DOM 样式</td></tr><tr><td><strong>动态尺寸调整</strong></td><td>使用 flexbox（Splitpanes）或 绝对定位 + transform（Vue Grid Layout）</td></tr><tr><td><strong>碰撞检测</strong></td><td>AABB 算法（检查矩形重叠）</td></tr><tr><td><strong>嵌套布局</strong></td><td>递归组件 + 上下文传递（如 provide/inject）</td></tr><tr><td><strong>性能优化</strong></td><td>防抖 resize 事件、避免直接操作 DOM（优先数据驱动）</td></tr></tbody></table><p><strong>如何自己实现一个简易版？</strong> ==如果你想手动实现类似功能，可以按以下步骤：==</p><ol><li><strong>基础结构</strong>==：用== ==flexbox== ==或== ==grid== ==布局划分区域。==</li><li><strong>拖拽交互</strong>==：========javascript========复制========splitter====.====onmousedown== ===== ==(====e====)== ===&gt;== =={====== ==const== ==startX== ===== ==e====.====clientX====;====== ==const== ==pane1Width== ===== ==pane1====.====offsetWidth====;====== ==== ==document====.====onmousemove== ===== ==(====e====)== ===&gt;== =={====== ==const== ==delta== ===== ==e====.====clientX== ==-== ==startX====;====== ==pane1====.====style====.====width== ===== ==<code>====${====pane1Width== ==+== ==delta====}====px</code>====;====== ==};====== ==== ==document====.====onmouseup== ===== ==()== ===&gt;== =={====== ==document====.====onmousemove== ===== ==null;====== ==};========};==</li><li><strong>数据同步</strong>==：将最终尺寸通过== ==v-model== ==抛给父组件。==</li></ol><p><strong>总结</strong></p><ul><li><strong>Splitpanes</strong>==：基于== ==flexbox== ==+ 鼠标事件，适合面板分割。==</li><li><strong>Vue Grid Layout</strong>==：基于== ==绝对定位== ==+ 网格系统，适合自由布局。==</li><li><strong>核心难点</strong>==：拖拽流畅性、碰撞检测、嵌套支持。==</li></ul><p>==如果你对某个库的具体实现细节感兴趣，可以直接阅读其源码（通常不超过 1000 行）。例如：==</p><ul><li>==Splitpanes 源码==</li><li>==Vue Grid Layout 源码==</li></ul><p>希望这些分析能帮助你理解底层原理！ 🛠️ &gt; 来自 &lt;<a href="https://chat.deepseek.com/a/chat/s/9c2caa9b-a223-4340-802e-82a4b5410ff9" target="_blank" rel="noreferrer">https://chat.deepseek.com/a/chat/s/9c2caa9b-a223-4340-802e-82a4b5410ff9</a>&gt;</p></div>',1)])])}const m=e(l,[["render",r]]);export{c as __pageData,m as default};
